const empresaId = $json.empresa_id;
const store = $getWorkflowStaticData('global');
store.ifoodTokens = store.ifoodTokens || {};
const cached = store.ifoodTokens[empresaId];
const valido = !!(cached && cached.expiresAt > Date.now() + 60000);
return [{
  json: {
    ...$json,
    access_token: valido ? cached.accessToken : null,
    token_valido: valido,
  },
}];

const ctx = $('Checar token em cache').item.json;
const store = $getWorkflowStaticData('global');
store.ifoodTokens = store.ifoodTokens || {};
store.ifoodTokens[ctx.empresa_id] = {
  accessToken: $json.accessToken,
  expiresAt: Date.now() + (($json.expiresIn || 21600) * 1000),
};
return [{
  json: { ...ctx, access_token: $json.accessToken, token_valido: true },
}];

const url = $('Webhook').item.json.body.imagem_url;
let imagemBase64 = null;
if (url) {
  try {
    const resp = await this.helpers.httpRequest({ url, encoding: 'arraybuffer', returnFullResponse: true });
    const contentType = (resp.headers['content-type'] || 'image/jpeg').split(';')[0];
    const base64 = Buffer.from(resp.body).toString('base64');
    imagemBase64 = `data:${contentType};base64,${base64}`;
  } catch (e) {
    imagemBase64 = null;
  }
}
return [{ json: { ...$json, imagem_base64: imagemBase64 } }];

const cfg = $('Buscar credenciais empresa').item.json;
const store = $getWorkflowStaticData('global');
store.food99Tokens = store.food99Tokens || {};
const cached = store.food99Tokens[cfg.id_loja_plataforma];
const valido = !!(cached && cached.expiresAt > Date.now() + 60000);
return [{
  json: {
    app_id_valor: cfg.api_key,
    app_shop_id_valor: cfg.id_loja_plataforma,
    api_secret: cfg.api_secret,
    auth_token: valido ? cached.authToken : null,
    token_valido: valido,
  },
}];

const ctx = $('Checar token 99Food em cache').item.json;
const resp = $json;
const tokenData = resp.data || {};
const ok = resp.errno === 0 && !!tokenData.auth_token;
const store = $getWorkflowStaticData('global');
store.food99Tokens = store.food99Tokens || {};
if (ok) {
  store.food99Tokens[ctx.app_shop_id_valor] = {
    authToken: tokenData.auth_token,
    expiresAt: tokenData.token_expiration_time ? tokenData.token_expiration_time * 1000 : Date.now() + 21600000,
  };
}
return [{ json: { ...ctx, auth_token: ok ? tokenData.auth_token : null, token_valido: ok, token_erro: ok ? null : (resp.errmsg || 'erro desconhecido ao obter token') } }];

const body = $('Webhook').item.json.body;
const catId = $('Buscar categoria mapeada 99Food').item.json.category_id_externo;

// Corta por code point (nao por char UTF-16) pra nunca quebrar acento/emoji.
function truncateCodepoints(str, max) {
  const arr = Array.from(str || '');
  if (arr.length <= max) return str || '';
  return arr.slice(0, max).join('');
}
function truncateWordBoundary(str, max) {
  const arr = Array.from(str || '');
  if (arr.length <= max) return str || '';
  const cut = arr.slice(0, max).join('');
  const lastSpace = cut.lastIndexOf(' ');
  return lastSpace > max * 0.6 ? cut.slice(0, lastSpace) : cut;
}

// item_name da 99Food e limitado a 50 char - a maioria dos nomes reais
// deste catalogo estoura isso (padrao de nomenclatura longo, ver memoria
// gestor_padrao_nome_produto). Quando trunca, o nome completo vai pro
// começo da descricao em vez de simplesmente se perder.
const nomeCompleto = body.nome || '';
const itemName = truncateWordBoundary(nomeCompleto, 50);
const nomeFoiTruncado = itemName !== nomeCompleto;
const descBase = nomeFoiTruncado ? (nomeCompleto + '\n\n' + (body.descricao || '')) : (body.descricao || '');
const shortDesc = truncateCodepoints(descBase.trim(), 400);

const priceCents = Math.round((body.preco || 0) * 100);
let activityPriceCents;
if (body.preco_promocional && body.preco_promocional > 0 && body.preco_promocional < body.preco) {
  const promoCents = Math.round(body.preco_promocional * 100);
  if (priceCents - promoCents >= priceCents * 0.01) activityPriceCents = promoCents;
}

const item = {
  app_item_id: body.produto_id,
  app_category_id: catId,
  upc: body.codigo_barras,
  item_name: itemName,
  price: priceCents,
  status: body.status_calculado === 'AVAILABLE' ? 1 : 2,
  item_tags: [],
};
if (shortDesc) item.short_desc = shortDesc;
if (activityPriceCents != null) item.activity_price = activityPriceCents;
if (body.imagem_url && /^https:\/\//.test(body.imagem_url)) item.head_img = body.imagem_url;

return [{ json: { item_list: [item] } }];
